#!/usr/bin/env bash
# Full CheXpert Plus attention head: RAD-DINO patch tokens of every study with a frontal
# image (NVFP4), then one head with Findings and Impression readouts sharing each
# label's query, trained on every labelled train study, 3 seeds. All on one node, so
# the three trainings read the ~110 GB store from its page cache, not 3 times over NFS.
# Then the pilot with seed 1's Findings labels: Qwen3.5-27B with the image (518 px),
# both sampling seeds, next to the Findings-only head, retrieval-only and image only
# (already generated by pilot-image.sh). Peak 4 GPUs.
set -euo pipefail
cd "$(dirname "$0")/.."

NODE=kg35-nvl01
s() { slurm/submit.sh --parsable --kill-on-invalid-dep=yes "$@"; }
B="labrag build-prompts --experiment pilot --section findings"
F=pilot/chexpertplus/findings
CLF=attn-nvfp4-seed1
SET=pilot
P=section-simple-image

tok=$(s -w $NODE --gres=gpu:1 --cpus-per-task=32 --mem=64G -- labrag embed --dataset chexpertplus --feature tokens)
clf=()
for seed in 1 2 3; do
  clf+=($(s -w $NODE -d afterok:$tok --gres=gpu:1 --cpus-per-task=16 --mem=64G -- labrag classify --dataset chexpertplus --classifier attn --tokens nvfp4 --seed $seed))
done
pro=$(s -d afterok:${clf[0]} -- $B --condition labrag --classifier $CLF-sections --prompt $P)
NEW="$F/labrag.$CLF-sections.chexbert14.u0/$P"
OLD="$F/labrag.$CLF.chexbert14.u0/$P $F/retrieval-only/section-naive-image
  $F/no-context/section-image"

gens() { for p in $2; do echo -n "$p/$1/$SET "; done; }
ids=""
runs=""
dep=""
for sampling in qwen3.5-thinking-32k qwen3.5-thinking-32k-seed2; do
  run=qwen3.5-27b-vision.$sampling
  g=$(s -d afterok:$pro --gres=gpu:1 -- labrag generate --prompts $NEW --set $SET --model qwen3.5-27b-vision --sampling $sampling)
  e=$(s -d afterok:$g --gres=gpu:1 -- labrag evaluate --generations $(gens $run "$NEW"))
  ids+=" $g $e"
  dep+=":$e"
  runs+=" $(gens $run "$NEW $OLD")"
done
cmp=$(s -d afterok$dep -- labrag compare --generations $runs --out $F/qwen3.5-27b.sections/$SET)
echo "embed $tok classify ${clf[*]} prompts $pro generate/evaluate$ids compare $cmp"
